function fmScalar(raw){
  var v=String(raw).trim();
  if(v==='') return '';
  if((v[0]==='"' && v.slice(-1)==='"') || (v[0]==="'" && v.slice(-1)==="'")) return v.slice(1,-1);
  if(v==='true') return true;
  if(v==='false') return false;
  if(v==='null' || v==='~') return null;
  if(/^-?\d+$/.test(v)) return parseInt(v,10);
  if(/^-?\d*\.\d+$/.test(v)) return parseFloat(v);
  if(v[0]==='[' && v.slice(-1)===']'){
    var inner=v.slice(1,-1).trim();
    if(!inner) return [];
    return inner.split(',').map(function(x){ return fmScalar(x); });
  }
  return v;
}
function fmSplit(text){
  var s=String(text==null?'':text).replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n');
  var m=s.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if(!m) return { has:false, raw:'', body:s };
  return { has:true, raw:m[1], body:m[2] };
}
function fmParse(text){
  var sp=fmSplit(text);
  if(!sp.has) return { error:null, has:false, data:{}, body:sp.body, order:[] };
  var lines=sp.raw.split('\n'), data={}, order=[], curKey=null, dup=[];
  for(var i=0;i<lines.length;i++){
    var ln=lines[i];
    if(!ln.trim() || /^\s*#/.test(ln)) continue;
    var li=ln.match(/^\s*-\s+(.*)$/);
    if(li && curKey){
      if(!Array.isArray(data[curKey])) data[curKey]=[];
      data[curKey].push(fmScalar(li[1]));
      continue;
    }
    var kv=ln.match(/^([A-Za-z0-9_.\-]+)\s*:\s*(.*)$/);
    if(!kv) return { error:'第 '+(i+1)+' 行无法解析：'+ln.trim() };
    var k=kv[1];
    if(Object.prototype.hasOwnProperty.call(data,k)) dup.push(k);
    else order.push(k);
    curKey=k;
    data[k] = kv[2].trim()==='' ? [] : fmScalar(kv[2]);
  }
  return { error:null, has:true, data:data, body:sp.body, order:order, dup:dup };
}
function fmDump(value){
  if(Array.isArray(value)) return '['+value.map(function(v){ return fmDump(v); }).join(', ')+']';
  if(value===null) return 'null';
  if(typeof value==='boolean' || typeof value==='number') return String(value);
  var s=String(value);
  return /[:#\[\]{}]|^\s|\s$/.test(s) ? '"'+s.replace(/"/g,'\\"')+'"' : s;
}
function fmStringify(data, order, body){
  var keys=(order&&order.length? order : Object.keys(data)), out='---\n';
  for(var i=0;i<keys.length;i++){
    var k=keys[i], v=data[k];
    if(Array.isArray(v) && v.length && v.some(function(x){ return typeof x==='string' && x.length>18; })){
      out += k+':\n';
      for(var j=0;j<v.length;j++) out += '  - '+fmDump(v[j])+'\n';
    } else out += k+': '+fmDump(v)+'\n';
  }
  return out+'---\n'+(body||'');
}
function fmLint(parsed, required){
  var issues=[];
  if(!parsed.has){ issues.push({ level:'error', msg:'\u7f3a\u5c11 front-matter \u5757' }); return issues; }
  var req=required||[];
  for(var i=0;i<req.length;i++)
    if(!Object.prototype.hasOwnProperty.call(parsed.data, req[i]))
      issues.push({ level:'error', msg:'\u7f3a\u5c11\u5fc5\u586b\u5b57\u6bb5\uff1a'+req[i] });
  for(var d=0; d<(parsed.dup||[]).length; d++)
    issues.push({ level:'warn', msg:'\u91cd\u590d\u5b57\u6bb5\uff1a'+parsed.dup[d] });
  if(parsed.data.title && String(parsed.data.title).length>60)
    issues.push({ level:'warn', msg:'title \u8d85\u8fc7 60 \u5b57\u7b26\uff0c\u4e0d\u5229\u4e8e SEO' });
  if(parsed.data.description && String(parsed.data.description).length>160)
    issues.push({ level:'warn', msg:'description \u8d85\u8fc7 160 \u5b57\u7b26' });
  return issues;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { fmScalar:fmScalar, fmSplit:fmSplit, fmParse:fmParse, fmDump:fmDump, fmStringify:fmStringify, fmLint:fmLint };
}
if (typeof window !== 'undefined') {
  window.FrontmatterForgePure = { fmScalar:fmScalar, fmSplit:fmSplit, fmParse:fmParse, fmDump:fmDump, fmStringify:fmStringify, fmLint:fmLint };
}
